<?php require 'config.php';require_login();$msg='';if($_SERVER['REQUEST_METHOD']==='POST' && trim($_POST['message'])){$s=$pdo->prepare('INSERT INTO feedback(user_id,message) VALUES(?,?)');$s->execute([$_SESSION['user_id'],trim($_POST['message'])]);$msg='Thank you for your feedback.';}?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>Customer feedback</h1><p><?=h($msg)?></p><form method="post"><textarea name="message" rows="5" required placeholder="Share your experience"></textarea><button>Submit feedback</button></form></div></div></body></html>